const _byKey = new Map();
LINGQI_GUA.forEach((g) => { _byKey.set(g.counts[0] * 25 + g.counts[1] * 5 + g.counts[2], g); });

// (上,中,下) 各 0-4 → 卦;越界/非整回 null
export function findLingqiGua(u, m, d) {
  const ok = (v) => Number.isInteger(v) && v >= 0 && v <= 4;
  if (!ok(u) || !ok(m) || !ok(d)) { return null; }
  return _byKey.get(u * 25 + m * 5 + d) || null;
}

// 卦序中文:1→'第一' … 124→'第一百二十四';125=純隂鏝(不入一百二十四数,提要口径)
export function lingqiOrdinalCn(id) {
  if (id === 125) { return '卦外'; }
  const CN = ['', '一', '二', '三', '四', '五', '六', '七', '八', '九'];
  const n = id | 0;
  if (n < 1 || n > 124) { return ''; }
  let s = '';
  if (n >= 100) { s += '一百'; }
  const r = n % 100;
  if (r >= 20) { s += CN[Math.floor(r / 10)] + '十' + (r % 10 ? CN[r % 10] : ''); }
  else if (r >= 10) { s += '十' + (r % 10 ? CN[r % 10] : ''); }
  else if (r > 0) { s += (n >= 100 ? '零' : '') + CN[r]; }
  return '第' + s;
}
